#include "agentflow/agent_callable_tool_host.hpp"
#include "agentflow/xlang_python.hpp"
inline void callable_authority_contract(const std::vector<std::string>& roots){
    for(const bool revoked:{false,true}){
        Directory directory;write(directory.path/"AGENTS.md","CALLABLE_AUTHORITY_GUIDANCE\n");write(directory.path/"authority_probe.py","def invoke(arguments):\n    with open(arguments['marker'], 'a', encoding='utf-8') as output:\n        output.write('once')\n    return {'text': arguments['text'].upper()}\n");WorkspaceTools workspace(directory.path.string());auto context=std::make_unique<RepositoryInstructionContext>(workspace,workspace.repository_instructions("."));context->prepare();PersistenceService store((directory.path/"state.sqlite").string(),roots);store.create_session("session","Actual callable pre-effect authority").get();store.start_prompt_run("run","session",R"({"content":"Call one trusted xlang3 fixture"})").get();store.transition("run",RunState::queued,RunState::running).get();
        auto callable=std::make_shared<XlangPythonCallable>(roots[0],roots[1],directory.path.string(),"authority_probe","invoke");const auto marker=directory.path/"effect.txt";const auto args=Json{{"marker",marker.string()},{"text","guarded"}}.dump();std::atomic<int> checks{0},resolutions{0};AgentCallableToolOwnerContext owner;owner.run_id="run";owner.workspace_id=workspace.identity();owner.offered_tool=[](const std::string& name){return name=="trusted_probe";};owner.repository_context_for_call=[&]{++resolutions;return context.get();};owner.permission_layers={{{"trusted_probe","*","ask"}}};owner.deadline=std::chrono::steady_clock::now()+10s;owner.bindings.push_back({{"trusted_probe","Actual xlang3 fixture callable",R"({"type":"object","properties":{"marker":{"type":"string"},"text":{"type":"string"}},"required":["marker","text"],"additionalProperties":false})"},[callable](const std::string& value,std::stop_token stop){return callable->invoke_json(value,stop);}});
        owner.before_effect=[&](const AgentCallableInvocation& actual,const std::string& operation,std::stop_token stop){need(!stop.stop_requested()&&actual.run_id=="run"&&actual.tool_name=="trusted_probe"&&actual.arguments_json==args&&store.operation(operation).get().state==OperationState::executing&&!std::filesystem::exists(marker),"Callable authority must see exact approved operation before the actual effect");++checks;if(revoked)throw ToolAccessDenied("Fixture authority retired after approval");};auto host=make_agent_callable_tool_host(store,owner);context=std::make_unique<RepositoryInstructionContext>(workspace,workspace.repository_instructions("."));context->prepare();
        AgentCallableInvocation call;call.run_id="run";call.attempt_id="synthetic-authority-turn";call.call_id="callable-authority";call.workspace_id=workspace.identity();call.tool_name="trusted_probe";call.arguments_json=args;std::stop_source stop;auto task=std::async(std::launch::async,[&]{return host->invoke(call,stop.get_token());});try{const auto proposal=pending(store,0);need(checks==0&&!std::filesystem::exists(marker),"Callable authority and effect must wait for actual approval");store.decide_operation(proposal.id,OperationDecision::allow,"callable-authority-controller").get();if(revoked){rejects<ToolAccessDenied>([&]{(void)task.get();});need(store.operation(proposal.id).get().state==OperationState::failed&&!std::filesystem::exists(marker),"Retired callable authority must retain known failure without dispatch");}else {const auto result=task.get();need(result.success&&Json::parse(result.output_json).at("text")=="GUARDED"&&read(marker)=="once"&&store.operation(proposal.id).get().state==OperationState::succeeded,"Allowed authority must retain one actual xlang3 effect and result");}need(checks==1&&resolutions==1,"Callable must resolve current guidance and check pre-effect authority once");}catch(...){stop.request_stop();if(task.valid())try{(void)task.get();}catch(...){}throw;}
        std::cout<<"Native callable pre-effect authority "<<(revoked?"revoked":"allowed")<<" verified actual approval, current guidance and xlang3 effect boundary."<<std::endl;
    }
}
